import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
import { OutlineService } from '../src/logos-engine/v6-outline-service.ts';

// Separate immutable addendum: attempt1's original 58 remains an archived
// mismatch. These expectations were generated by unchanged Python, including
// its comprehension variable shadowing, not from the corrected native code.
const fixture = JSON.parse(gunzipSync(readFileSync(new URL('./fixtures/v6-outline-local-count-reference.json.gz', import.meta.url))).toString());
for (const row of fixture.cases) test(`outline exact source local/remote count ${row.id}`, async () => {
  const owner = await OutlineService.create(), a = row.arguments; owner.restore(row.seedState);
  assert.deepEqual(await owner.recordSource(a.before, a.after, a.command, a.first, a.second, a.proposal, a.index), row.value);
  assert.deepEqual(owner.state(), row.afterState);
});
